-- ============ Aktualności ============
insert into public.news (title, body, links, published_at)
select v.title, v.body, v.links::jsonb, v.published_at::timestamptz from (values
  ('Nowa strona RapHouse',
   'Odświeżyliśmy stronę studia. W jednym miejscu znajdziesz ofertę, cennik, nasze realizacje, katalog bitów i aktualności ze studia.

Masz numer do nagrania? Zadzwoń albo napisz — ustalimy termin sesji.',
   '[{"label": "Katalog bitów", "url": "/bity"}, {"label": "Kontakt", "url": "/#kontakt"}]',
   now()),
  ('Katalog bitów online',
   'Cały katalog bitów możesz teraz odsłuchać bezpośrednio na stronie. Bity podzieliliśmy na trzy klimaty: Bangery / Mroczne, RnB / Pop / Club / 80s oraz Spokojne / Klimatyczne. Przy każdym znajdziesz tonację, tempo i przedział cenowy.

Spodobał Ci się któryś? Podaj nam tytuł bitu, a wrócimy z finalną wyceną. Wolisz coś szytego na miarę? Producent zrobi bit od podstaw pod Twój numer.',
   '[{"label": "Odsłuchaj bity", "url": "/bity"}]',
